        "current": "const workshopScopes=new WeakMap();\nasync function workshopCheck(c,ctx){const token=Object.freeze({}),scope={c,transaction:itemTransactionIdentity(c),ctx,active:true};workshopScopes.set(token,scope);try{return await workshopFloorServiceAdmission(c,ctx,token);}finally{scope.active=false;}}\nexport function assertWorkshopFloorServiceScope(c,ctx,token){assertItemTransaction(c);const scope=workshopScopes.get(token);if(!scope?.active||scope.c!==c||scope.transaction!==itemTransactionIdentity(c)||scope.ctx!==ctx)throw new GameError('workshop_floor','canonical_service_scope');return true;}\n\n// Source-private, one-use witness minted only after a new canonical request ACK.\n// Historical replays above return before this brand is minted.\nexport const commercialCampaignCompletionRevision='commercial_campaign_v1';\nconst commercialFresh=new WeakMap();\nasync function commercialCommissionWitness(c,receipt,consume){\n  assertItemTransaction(c);\n  const proof=receipt&&commercialFresh.get(receipt);\n  if(!proof||proof.client!==c||proof.transaction!==itemTransactionIdentity(c))fail('commercial_fresh_source');\n  if(consume)commercialFresh.delete(receipt);\n  try{\n    if(hash(receipt)!==proof.receiptHash||!['fund','accept','complete'].includes(proof.action))fail('commercial_fresh_source');\n    const request=(await c.query('SELECT * FROM commissioned_crafting_requests WHERE account_id=$1 AND key_hash=$2',[proof.account,proof.keyHash])).rows[0];\n    if(!request||request.body_hash!==proof.bodyHash||request.run_id!==proof.run||request.account_ref!==proof.account||request.original_character!==proof.actor||hash(request.receipt)!==proof.receiptHash)fail('commercial_request_ack');\n    const row=(await c.query('SELECT * FROM commissioned_crafting_contracts WHERE id=$1',[receipt.commissionId])).rows[0];\n    if(!row||hash(source(row))!==row.source_hash||row.source_hash!==receipt.sourceHash||row.status!==({fund:'funded',accept:'accepted',complete:'completed'})[proof.action])fail('commercial_source');\n    const expected=proof.action==='fund'?normalize('fund',{businessId:row.business_id,feeCash:Number(row.fee_total),lifetimeSeconds:proof.terms.lifetimeSeconds,consent:true}):normalize(proof.action,{commissionId:row.id,sourceHash:row.source_hash,consent:true});\n    if(stable(expected)!==stable(proof.terms)||proof.actor!==(proof.action==='fund'?row.customer_character:row.maker_character)||proof.account!==(proof.action==='fund'?row.customer_account:row.maker_account))fail('commercial_original');\n    if(+await clock(c)>=+new Date(row.expires_at))fail('expired');\n    for(const [original,account]of [[row.customer_character,row.customer_account],[row.maker_character,row.maker_account]]){\n      const ch=(await c.query('SELECT id,account_id,alive,cash FROM characters WHERE id=$1',[original])).rows[0];\n      if(!ch?.alive||ch.account_id!==account||(await current(c,account))!==original||!Number.isSafeInteger(Number(ch.cash))||(await c.query('SELECT status FROM accounts WHERE id=$1',[account])).rows[0]?.status!=='active')fail('commercial_original');\n    }\n    const journals=(await c.query(\"SELECT id,character_id,currency,amount,reason FROM transactions WHERE counterparty=$1 AND reason IN ('commissioned_crafting:reserve','commissioned_crafting:fee','commissioned_crafting:refund') ORDER BY id\",[row.id])).rows;\n    if(proof.action==='complete'){\n      if(Number(row.fee_remaining)!==0||Number(row.fee_paid)!==Number(row.fee_total)||Number(row.fee_refunded)!==0||!await completionWitness(c,row))fail('commercial_completion');\n      const reserve=journals.filter(t=>t.reason==='commissioned_crafting:reserve'),paid=journals.filter(t=>t.reason==='commissioned_crafting:fee');\n      if(journals.length!==2||reserve.length!==1||paid.length!==1||reserve[0].id!==row.reserve_transaction||reserve[0].character_id!==row.customer_character||Number(reserve[0].amount)!==-Number(row.fee_total)||paid[0].character_id!==row.maker_character||Number(paid[0].amount)!==Number(row.fee_total)||journals.some(t=>t.currency!=='cash')||paid[0].id!==row.settlement.feeTransaction)fail('commercial_budget');\n      if(!await inputWitness(c,row,row.fund_guard,owner(row.customer_account),operation(row.id)))fail('commercial_funding_history');\n    }else await fundedWitness(c,row);\n    return Object.freeze({family:'commission',phase:proof.action,requestKeyHash:proof.keyHash,bodyHash:proof.bodyHash,actor:proof.actor,account:proof.account,source:source(row),sourceHash:row.source_hash,status:row.status,journals,outputItemId:proof.action==='complete'?row.settlement.outputItemId:null,settlement:proof.action==='complete'?row.settlement:null});\n  }catch(error){poisonItemTransaction(c,error);throw error;}\n}\nexport const inspectCommercialCommission=(c,receipt)=>commercialCommissionWitness(c,receipt,false);\nexport const consumeCommercialCommission=(c,receipt)=>commercialCommissionWitness(c,receipt,true);\n",
